entries[314791] = { ["name"] = "Machtverschiebung", ["text"] = "Pakt-Fähigkeit\n5% von GrundmanaKanalisiert (Wirken in 4 sek.) 1 min Abklingzeit\nZieht Kraft aus dem Boden unter Euch und fügt Gegnern innerhalb von 18 Metern im Verlauf von 4 Sek. [(60.996% der Zaubermacht) * 4] Naturschaden zu.\n\nWährend der Kanalisierung werden die Abklingzeiten Eurer Magierfähigkeiten im Verlauf von 4 Sek. um 10 Sek. verringert." }
