entries[315288] = { ["name"] = "Zauberstab der Erfrierung", ["text"] = "Animabonus\nSofort\nWenn ein Gegner getroffen wird, erleidet er zusätzlich eine Erfrierung, die ihm Schaden in Höhe von 50% seiner aktuellen Gesundheit zufügt. Nach 4 Sek. erhält der Gegner im Verlauf von 10 Sek. die verlorene Gesundheit zurück.\n\nKreaturen können nur einmal eine Erfrierung erleiden.\n(1s Abklingzeit)" }
entries[315289] = { ["name"] = "Zauberstab der Erfrierung", ["text"] = "Animabonus\n40 Meter Reichweite\nSofort\nWenn ein Gegner getroffen wird, erleidet er zusätzlich eine Erfrierung, die ihm Schaden in Höhe von 50% seiner aktuellen Gesundheit zufügt. Nach 4 Sek. erhält der Gegner im Verlauf von 10 Sek. die verlorene Gesundheit zurück.\n\nKreaturen können nur einmal eine Erfrierung erleiden." }
