entries[315291] = { ["name"] = "Verschlungener Abgrund", ["text"] = "Unbegrenzte Reichweite\nSofort\nEin Bereich ohne jegliche Magie, in dem Spielercharaktere und Kreaturen zum Schweigen gebracht werden und nicht geheilt werden können, aber auch immun gegen jegliche sonstige Magie sind.\n\n'Verschlungener Abgrund' entzieht zusätzlich alle 2 Sek. Mana und verursacht dabei 3752 Schattenschaden. Dieser Effekt ist stapelbar.\n\nSobald der Abgrund kollabiert, fügt er allen Einheiten innerhalb von 9 Metern 23452 Schattenschaden zu." }
