entries[315305] = { ["name"] = "Verbotenes Mana", ["text"] = "Unbegrenzte Reichweite\nSofort\nMa'ut zieht Manakugeln aus den Altären, die ihn umgeben.\n\nSpielercharaktere oder Kreaturen, die eine Kugel berühren, explodieren und fügen allen Spielercharakteren Arkanschaden zu, dessen Höhe von der zurückgelegten Strecke der Kugel abhängt. Jede Manakugel, die Ma'ut erreicht, stellt bis zu 100% seines Manas wieder her.\n\nSpielercharaktere, die die Kugel berühren, werden mit ' Verbotenes Mana ' belegt." }
